<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import {ArrowUp,Square,SlidersHorizontal,RefreshCw} from 'lucide-vue-next'
import {api,newKey} from '../api'
import {cacheGet,cacheSet} from '../platform/bridge'
import {useRequestScope} from '../platform/request-scope'
import {useApp} from '../stores/app'
import {worldApi} from '../world/api'
import type {WorldTask} from '../world/types'
import PageHeader from '../workspace/PageHeader.vue'
import Sheet from '../components/Sheet.vue'
import PublicStreamText from '../components/PublicStreamText.vue'
import WorldAppearanceProvider from '../components/WorldAppearanceProvider.vue'
import CharacterAvatar from '../components/CharacterAvatar.vue'
import AccountAvatar from '../components/AccountAvatar.vue'
import ModelControlButton from './ModelControlButton.vue'
import PlaySettings from './PlaySettings.vue'
import PrivateBackup from '../components/PrivateBackup.vue'
import TaskProgress from '../experience/TaskProgress.vue'
import type {WorldChat,ChatMessage} from './types'
import {restoreChatDraft,type ChatDraft,type ChatIntent} from './chat-draft'
const route=useRoute(),id=String(route.params.sessionId),root='/play-controls/world-chats/'+id,capture=useRequestScope(),app=useApp(),chat=ref<WorldChat>(),task=ref<WorldTask>(),draft=ref(''),busy=ref(false),error=ref(''),notice=ref(''),settings=ref(false),sourceConfirm=ref(false),renaming=ref(false),name=ref(''),log=ref<HTMLElement>()
const modelSettings=ref<InstanceType<typeof PlaySettings>>(),modelButton=ref<InstanceType<typeof ModelControlButton>>()
const backup=ref(false),deleting=ref(false),sourcePreview=ref<{fromTime:string;toTime:string;changed:boolean;addedFacts:{title:string;text:string}[]}>(),messageSearch=ref(''),matches=ref<ChatMessage[]>([]),sourceOpen=ref(false),locatedSequence=ref(0),searching=ref(false),olderBusy=ref(false)
async function closeSettings(){if(await modelSettings.value?.requestClose())settings.value=false}
const intent=ref<ChatIntent|null>(null),running=computed(()=>!!chat.value?.pendingTaskId),sourceLink=computed(()=>chat.value?'/worlds/'+chat.value.worldId+'/play?line='+chat.value.lineId:'/works'),slot=computed(()=>chat.value?'world-chat-draft:'+chat.value.worldId+':'+chat.value.lineId+':'+id:'')
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,loadedDraft=false
async function persist(){if(slot.value)await cacheSet(slot.value,{worldId:chat.value!.worldId,lineId:chat.value!.lineId,draft:draft.value,intent:intent.value})}
watch(draft,()=>{if(loadedDraft)void persist().catch(()=>{error.value='输入暂时无法保存在此设备，请保持页面打开。'})})
function bottom(){void nextTick(()=>{const element=log.value;if(element&&element.scrollHeight-element.scrollTop-element.clientHeight<500)element.scrollTop=element.scrollHeight})}
async function older(){if(!chat.value?.messages?.length||olderBusy.value)return;olderBusy.value=true;const scope=capture();try{const result=await api<{items:ChatMessage[]}>(root+'/messages?before='+chat.value.messages[0].sequence);if(scope.valid()&&!disposed)chat.value.messages=[...result.items.filter(m=>!chat.value!.messages!.some(x=>x.id===m.id)),...chat.value.messages]}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)olderBusy.value=false}}
async function fetchChat(){const scope=capture(),result=await api<WorldChat>(root);if(!scope.valid()||disposed)return;chat.value=result;name.value=result.name;if(!loadedDraft){const saved=await cacheGet<ChatDraft>(slot.value);if(!scope.valid()||disposed)return;const restored=restoreChatDraft(saved,result.messages||[]);draft.value=restored.draft;intent.value=restored.intent;loadedDraft=true;if(saved?.intent&&!restored.intent)await persist()}bottom()}
function schedule(delay=1000){clearTimeout(timer);if(!disposed)timer=setTimeout(()=>void poll(),delay)}
async function poll(){const scope=capture(),pending=chat.value?.pendingTaskId;if(!pending||disposed)return;try{const result=await worldApi<WorldTask>('/tasks/'+pending);if(!scope.valid()||disposed)return;task.value=result;bottom();if(['succeeded','failed','cancelled'].includes(result.state)&&result.persistenceState!=='recoverable'){await fetchChat();if(result.state!=='succeeded')notice.value=result.state==='cancelled'?'已停止，收到的回复已保留。':'这次回复没有完整完成，已收到的内容会保留。';return}schedule()}catch(e){if(scope.valid()&&!disposed){error.value=(e as Error).message;schedule(2500)}}}
async function load(){const scope=capture();error.value='';try{await fetchChat();if(scope.valid()&&!disposed)await locateSource();if(scope.valid()&&!disposed&&chat.value?.pendingTaskId)schedule(0)}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}}
async function send(){if(busy.value||running.value||!app.online||(!draft.value.trim()&&!intent.value))return;const scope=capture();busy.value=true;error.value='';notice.value='';try{if(!intent.value)intent.value={message:draft.value.trim(),turnId:newKey(),key:newKey()};await persist();if(!scope.valid()||disposed)return;const current=intent.value!;await api(root+'/send',{method:'POST',body:{message:current.message,turnId:current.turnId},key:current.key});if(!scope.valid()||disposed)return;intent.value=null;draft.value='';await persist();task.value=undefined;await fetchChat();schedule(0)}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)busy.value=false}}
async function stop(){if(!chat.value?.pendingTaskId)return;const scope=capture();try{await worldApi('/tasks/'+chat.value.pendingTaskId+'/cancel',{method:'POST',body:{}});if(scope.valid()&&!disposed){notice.value='正在停止并保存已收到的内容…';schedule(0)}}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}}
async function update(advance:boolean){if(!chat.value||busy.value||running.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await api<WorldChat>(root,{method:'PATCH',key:newKey(),body:{expectedVersion:chat.value.version,...(advance?{updateSource:true}:{name:name.value})}});if(scope.valid()&&!disposed){chat.value={...result,messages:chat.value.messages};sourceConfirm.value=false;renaming.value=false;notice.value=advance?'来源已更新到当前主线进度，以后的消息会使用新资料。历史消息保留原来源。':'对话名称已保存。'}}catch(e){if(scope.valid()&&!disposed)error.value=(e as Error).message}finally{if(scope.valid()&&!disposed)busy.value=false}}

async function previewSource(){const scope=capture();try{sourcePreview.value=await api(root+'/source-preview');if(scope.valid())sourceConfirm.value=true}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function archive(){if(!chat.value||running.value||busy.value)return;const scope=capture();busy.value=true;try{const result=await api<WorldChat>(root,{method:'PATCH',key:newKey(),body:{expectedVersion:chat.value.version,status:chat.value.status==='archived'?'active':'archived'}});if(scope.valid())chat.value={...result,messages:chat.value.messages}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function remove(){if(!chat.value||running.value||busy.value)return;const scope=capture();busy.value=true;try{await api(root+'?expectedVersion='+chat.value.version,{method:'DELETE'});if(scope.valid()){await cacheSet(slot.value,null);chat.value=undefined;deleting.value=false;notice.value='这段对话已删除，来源世界及其他对话保持原状。'}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function exportText(){const scope=capture();try{const result=await api<{text:string;name:string}>(root+'/transcript');if(!scope.valid())return;const url=URL.createObjectURL(new Blob([result.text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=result.name.replace(/[\\/:*?"<>|]/g,'_')+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function searchMessages(){const scope=capture();searching.value=true;try{const result=await api<{items:ChatMessage[]}>(root+'/messages?q='+encodeURIComponent(messageSearch.value));if(scope.valid())matches.value=result.items}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())searching.value=false}}

function keyboard(event:KeyboardEvent){if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();void send()}}
function resume(){if(chat.value?.pendingTaskId)schedule(0);else void load()}
async function locateSource(){const sequence=Number(route.query.message);if(!Number.isSafeInteger(sequence)||sequence<1)return;const check=capture();try{const result=await api<{items:ChatMessage[]}>(root+'/messages?around='+sequence);if(check.valid()&&!disposed){matches.value=result.items;sourceOpen.value=true;locatedSequence.value=sequence;notice.value='已定位第 '+sequence+' 条附近的原消息；这些消息不会写入主线。';await nextTick();if(check.valid()&&!disposed)document.getElementById('chat-source-message-'+sequence)?.scrollIntoView({block:'center'})}}catch(e){if(check.valid())error.value=(e as Error).message}}
watch(()=>route.query.message,()=>{settings.value=false;if(chat.value?.pendingTaskId)schedule(0);void locateSource()})
onMounted(()=>{void load();window.addEventListener('reader-resume',resume);window.addEventListener('online',resume)})
onUnmounted(()=>{disposed=true;clearTimeout(timer);window.removeEventListener('reader-resume',resume);window.removeEventListener('online',resume)})
</script>
<template><WorldAppearanceProvider :world-id="chat?.worldId" :line-id="chat?.lineId" account><div class="workspace-page world-chat-page"><PageHeader :title="chat?.name||'角色独立对话'" eyebrow="我的对话" description="与人物单独聊聊，主线的时间、物品和结局保持原状。"><ModelControlButton v-if="chat" ref="modelButton" kind="chats" :identity="chat.id" @open="settings=true"/><button :disabled="!chat||busy||!app.online" @click="backup=true">导出聊天与记忆</button><button :disabled="!chat||running||busy" @click="renaming=true">修改名称</button><button :disabled="!chat||busy" @click="exportText">导出对话文本</button><button :disabled="!chat||running||busy" @click="archive">{{chat?.status==='archived'?'恢复对话':'归档对话'}}</button><button class="danger" :disabled="!chat||running||busy" @click="deleting=true">删除这段对话</button></PageHeader><p v-if="error" class="error" role="alert">{{error}} <button :disabled="busy" @click="load">重新连接</button></p><p v-if="notice" role="status">{{notice}}</p><RouterLink v-if="!chat&&notice" to="/conversations">返回对话列表</RouterLink><p v-if="!chat&&!error&&!notice" role="status">正在读取独立对话…</p><template v-if="chat"><section class="world-chat-source"><div><div class="chat-speaker"><CharacterAvatar :entity-id="chat.characterId" :name="chat.characterName"/><strong>{{chat.characterName}}</strong></div><p>{{chat.worldTitle}} · {{chat.snapshot.lineName}} · {{chat.snapshot.timeLabel}}</p><small>人物资料固定在开始聊天时的进度；新主线进展需要手动更新。</small></div><div class="world-chat-actions"><RouterLink :to="sourceLink" class="inline-link">返回主线</RouterLink><button :disabled="running||busy||!app.online" @click="previewSource"><RefreshCw :size="16"/>更新人物来源</button></div></section><details :open="sourceOpen" @toggle="sourceOpen=($event.target as HTMLDetailsElement).open"><summary>搜索与来源消息</summary><form @submit.prevent="searchMessages"><label>消息关键词<input v-model="messageSearch" maxlength="100" required></label><button :disabled="searching">搜索历史消息</button></form><p v-if="messageSearch&&!searching&&!matches.length">没有匹配的消息。</p><article v-for="m in matches" :key="m.id" :id="'chat-source-message-'+m.sequence" :class="{'chat-source-target':locatedSequence===m.sequence}"><small>第 {{m.sequence}} 条 · {{m.role==='user'?'你':chat.characterName}}</small><p style="white-space:pre-wrap">{{m.text}}</p></article></details><section ref="log" class="world-chat-log" role="log" aria-label="独立聊天记录" aria-live="polite"><button v-if="chat.messages?.length&&chat.messages[0].sequence>1" @click="older">查看更早的消息</button><div v-if="!chat.messages?.length&&!running" class="empty"><h2>和 {{chat.characterName}} 打个招呼</h2><p>{{chat.snapshot.character.description}}</p><p>这里的谈话只保存在这段对话里。</p></div><article v-for="message in chat.messages" :key="message.id" class="world-chat-message" :class="message.role"><div class="chat-speaker"><AccountAvatar v-if="message.role==='user'"/><CharacterAvatar v-else :entity-id="chat.characterId" :name="chat.characterName"/><strong>{{message.role==='user'?'你':chat.characterName}}</strong></div><p>{{message.text}}</p><small v-if="message.role==='assistant'">{{message.modelName}} · {{message.status==='interrupted'?'收到的部分回复':'已保存'}}</small><small v-if="message.checkpointId!==chat.checkpointId">来源：此前的故事进度</small></article><article v-if="running" class="world-chat-message assistant"><div class="chat-speaker"><CharacterAvatar :entity-id="chat.characterId" :name="chat.characterName"/><strong>{{chat.characterName}}</strong></div><PublicStreamText v-if="task?.stream.text" :text="task.stream.text" :content-id="task.stream.contentId||task.id" :stream-version="task.stream.streamVersion||1"/><p v-else role="status">{{task?.persistenceState==='recoverable'?'正在恢复已收到的回复…':'正在思考…'}}</p><TaskProgress :progress="task?.progress"/></article></section><p v-if="chat.status==='archived'" role="status">这段对话已归档，恢复后可以继续发送。</p><form v-else class="world-chat-compose" @submit.prevent="send"><p v-if="intent&&!running" class="product-hint">上次发送结果尚未确认。重试会查询并继续同一条消息，不会重复发送。</p><label class="sr-only" for="world-chat-message">给人物的消息</label><textarea id="world-chat-message" v-model="draft" :disabled="busy||running||!!intent" maxlength="4000" rows="3" :placeholder="'想对 '+chat.characterName+' 说些什么？'" @keydown="keyboard"></textarea><div class="world-chat-actions"><small>{{!app.online?'离线 · 输入已保留':'独立对话 · 不改变主线状态'}}</small><button v-if="running" type="button" @click="stop"><Square :size="18"/>停止回复</button><button v-else class="primary" :disabled="busy||!app.online||!draft.trim()&&!intent" type="submit"><ArrowUp :size="18"/>{{intent?'重试发送':busy?'正在发送…':'发送'}}</button></div></form></template><Sheet v-if="deleting&&chat" title="删除这段对话" @close="deleting=false"><p>删除本对话的所有消息和手动记忆，无法撤销。来源世界、主线进度及其他对话保持原状；已导出的备份由你保管。</p><button :disabled="busy" @click="deleting=false">保留对话</button><button class="danger" :disabled="busy||running" @click="remove">确认删除</button></Sheet><Sheet v-if="backup&&chat" title="导出聊天与记忆" @close="backup=false"><p>随来源故事一起保存全部独立聊天与记忆，恢复后可以从相同时间点继续对话。下载的文件可在“账号设置 → 数据与备份”中导入。</p><PrivateBackup mode="export" :story-id="'world-'+chat.worldId"/></Sheet><Sheet v-if="settings&&chat" title="对话模型与记忆" @close="closeSettings"><PlaySettings ref="modelSettings" @saved="modelButton?.refresh()" kind="chats" :identity="chat.id"/></Sheet><Sheet v-if="sourceConfirm&&chat" title="更新人物来源" @close="sourceConfirm=false"><p v-if="sourcePreview">{{sourcePreview.fromTime}} → {{sourcePreview.toTime}} · {{sourcePreview.changed?'来源将前进':'当前已是这个时间点'}}</p><ul v-if="sourcePreview?.addedFacts.length"><li v-for="fact in sourcePreview.addedFacts" :key="fact.title">新增已知：{{fact.title}}</li></ul><p>以后发送的消息会使用当前主线进度中的人物资料与已知事实。之前的聊天记录保留原来源，聊天内容仍不会写回主线。</p><button class="primary" :disabled="running||busy" @click="update(true)">确认更新来源</button></Sheet><Sheet v-if="renaming&&chat" title="修改对话名称" @close="renaming=false"><label>对话名称<input aria-label="对话名称" v-model="name" maxlength="120"></label><button class="primary" :disabled="running||busy||!name.trim()" @click="update(false)">保存名称</button></Sheet></div></WorldAppearanceProvider></template>
<style scoped>.chat-speaker{display:flex;align-items:center;gap:10px;white-space:normal}.chat-source-target{border:2px solid var(--accent);border-radius:12px;padding:16px;background:var(--wash)}.world-chat-page{max-width:1120px}.world-chat-source{display:flex;justify-content:space-between;gap:16px;padding:20px;border:1px solid var(--edge);border-radius:14px;background:var(--paper)}.world-chat-source p{margin:8px 0}.world-chat-actions{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.world-chat-log{height:clamp(300px,52dvh,750px);overflow:auto;overscroll-behavior:contain;padding:24px 4px;scrollbar-gutter:stable}.world-chat-message{padding:18px 22px;margin:16px 0;max-width:85%;border:1px solid var(--edge);border-radius:14px;overflow-wrap:anywhere;white-space:pre-wrap;background:var(--paper)}.world-chat-message.user{margin-left:auto;background:var(--wash)}.world-chat-message small{color:var(--quiet);display:block;font-size:12px}.world-chat-message p{line-height:1.9}.world-chat-compose{padding:16px;background:var(--paper);border:1px solid var(--edge);border-radius:14px;margin-bottom:env(safe-area-inset-bottom)}.world-chat-compose textarea{width:100%;resize:vertical;min-height:88px;border:0;background:transparent}.world-chat-page button{min-height:44px}.world-chat-page input{width:100%}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:767px){.world-chat-source{display:block;padding:14px}.world-chat-source .world-chat-actions{margin-top:12px}.world-chat-message{max-width:94%;padding:14px}.world-chat-log{height:45dvh;min-height:280px}.world-chat-compose{padding:12px}}</style>
